try{let saved=JSON.parse(localStorage.getItem('planta-v1'));if(saved&&validItems(saved.items)){items=saved.items;$('#name').value=String(saved.name||'Mi plano')}else throw Error()}catch{let walls=[[-350,-250,350,-250],[350,-250,350,250],[350,250,-350,250],[-350,250,-350,-250],[90,-250,90,-40],[90,50,90,250],[-350,60,-170,60],[-80,60,90,60]];items=walls.map(v=>({id:uid(),kind:'line',a:{x:v[0],y:v[1]},b:{x:v[2],y:v[3]},color:'#3f5346',style:'solid'}));[['Sofá',-250,-100],['Mesa',-65,-80],['Cama doble',220,-110],['Planta',-290,-190],['Inodoro',-280,160],['Lavabo',-160,195],['Puerta',90,5],['Ventana',-100,-250]].forEach(([name,x,y])=>{let t=types.find(t=>t[0]===name);items.push({id:uid(),kind:'object',name,type:t[4],w:t[2],h:t[3],angle:0,x,y})});$('#name').value='Mi casa · Ejemplo'}catalog();new ResizeObserver(resize).observe(c);setMode('draw');
function exportCanvas(){let old={...view},oldW=W,oldH=H,oldSelection=selection,oldAction=action;const out=document.createElement('canvas');let pts=items.flatMap(o=>o.kind==='line'?[o.a,o.b]:[{x:o.x-Math.hypot(o.w,o.h)/2,y:o.y-Math.hypot(o.w,o.h)/2},{x:o.x+Math.hypot(o.w,o.h)/2,y:o.y+Math.hypot(o.w,o.h)/2}]);if(!pts.length)pts=[{x:-100,y:-100},{x:100,y:100}];let minx=Math.min(...pts.map(p=>p.x)),maxx=Math.max(...pts.map(p=>p.x)),miny=Math.min(...pts.map(p=>p.y)),maxy=Math.max(...pts.map(p=>p.y));let bw=Math.max(100,maxx-minx),bh=Math.max(100,maxy-miny);let s=Math.min(3,2200/Math.max(bw,bh));out.width=Math.ceil(bw*s+160);out.height=Math.ceil(bh*s+160);try{W=out.width;H=out.height;c.width=W;c.height=H;ctx.setTransform(1,0,0,1,0,0);view={x:80-minx*s,y:80-miny*s,s};selection=null;action=null;render();out.getContext('2d').drawImage(c,0,0)}finally{view=old;W=oldW;H=oldH;selection=oldSelection;action=oldAction;resize()}return out}
function makePDF(canvas){let raw=atob(canvas.toDataURL('image/jpeg',.94).split(',')[1]),jpg=Uint8Array.from(raw,x=>x.charCodeAt(0)),land=canvas.width>canvas.height,pw=land?842:595,ph=land?595:842,ratio=Math.min((pw-48)/canvas.width,(ph-48)/canvas.height),iw=canvas.width*ratio,ih=canvas.height*ratio,content=`q ${iw} 0 0 ${ih} ${(pw-iw)/2} ${(ph-ih)/2} cm /Im0 Do Q`,enc=new TextEncoder(),parts=[],offsets=[0],length=0;function push(v){let b=typeof v==='string'?enc.encode(v):v;parts.push(b);length+=b.length}function obj(n,t){offsets[n]=length;push(n+' 0 obj\n'+t+'\nendobj\n')}push('%PDF-1.4\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');obj(3,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${pw} ${ph}] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>`);offsets[4]=length;push(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width ${canvas.width} /Height ${canvas.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${jpg.length} >>\nstream\n`);push(jpg);push('\nendstream\nendobj\n');obj(5,`<< /Length ${enc.encode(content).length} >>\nstream\n${content}\nendstream`);let start=length;push('xref\n0 6\n0000000000 65535 f \n');for(let n=1;n<=5;n++)push(String(offsets[n]).padStart(10,'0')+' 00000 n \n');push(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`);return new Blob(parts,{type:'application/pdf'})}
$('#export').onchange=async e=>{let format=e.target.value;e.target.value='';if(!format)return;let name=$('#name').value||'plano';if(format==='json'){download(JSON.stringify({version:1,name,items},null,2),name+'.json','application/json');toast('Proyecto JSON guardado en Descargas');return}try{await Promise.all(Object.values(imgs).map(im=>im.decode()));let output=exportCanvas();if(format==='png'){output.toBlob(blob=>download(blob,name+'.png','image/png'))}else download(makePDF(output),name+'.pdf','application/pdf');toast('Plano completo exportado')}catch(err){toast('No se pudo exportar el plano. Inténtalo de nuevo.')}};
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false});$('#install').onclick=async()=>{if(!installPrompt)return;await installPrompt.prompt();installPrompt=null;$('#install').hidden=true};window.addEventListener('appinstalled',()=>{$('#install').hidden=true;toast('Planta instalada')});if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
